<script lang="ts">
 import {app,run} from '../app.svelte';import {claimStore} from '../store';import {categories,ruleKeys,type RuleKey,type Policy,type Claim} from '../types';import {checkClaim} from '../policy';import {todayLocal} from '../sample';import {decimal,inputMoney} from '../money';import Icon from '../components/Icon.svelte';import Findings from '../components/Findings.svelte';
 let p:Policy=claimStore.policyFor();let testId=app.data!.claims[0]?.id||'',testAmount='1500.00';let holidayText=p.holidays.join(', ');let error='';
 const names:Record<RuleKey,string>={daily:'Daily category limits',claimCap:'Total claim cap',monthly:'Monthly category limits',receiptAmount:'Receipt amount threshold',receiptCategories:'Receipt-required categories',duplicate:'Duplicate expenses & receipts',late:'Late submission',future:'Future-dated expenses',trip:'Expenses outside trip dates',mileageDay:'Daily mileage cap',mileageRate:'Maximum mileage rate',allowed:'Department & grade eligibility',entertainment:'Client entertainment',weekend:'Weekends & holidays',tax:'Missing or inconsistent tax'};
 const monetary:RuleKey[]=['claimCap','receiptAmount','mileageRate','entertainment'];
 $: sample=app.data!.claims.find(c=>c.id===testId);$: testClaim=sample?testCopy(sample,testAmount):null;$: testFindings=testClaim?checkClaim(testClaim,p,app.data!.claims,todayLocal()):[];
 function testCopy(c:Claim,amount:string){const clone=JSON.parse(JSON.stringify(c)) as Claim;try{if(clone.lines[0]){clone.lines[0].kind='expense';clone.lines[0].currency='INR';clone.lines[0].amount=decimal(amount);}}catch{ /* Invalid sample input is handled by the numeric input. */ }return clone;}
 function value(key:RuleKey,v:string){try{p.rules[key].value=decimal(v,monetary.includes(key)?2:key==='mileageDay'?3:0);p={...p};error='';}catch(e){error=(e as Error).message;}}
 async function save(){p.holidays=holidayText.split(',').map(d=>d.trim()).filter(Boolean);const ok=await run(()=>{claimStore.setPolicy(p);return true;},'New policy version published. Existing submissions keep their version.');if(ok)p=claimStore.policyFor();}
 function allowed(group:'allowedDepartments'|'allowedGrades',name:string,category:typeof categories[number],checked:boolean){p[group][name]=checked?[...p[group][name],category]:p[group][name].filter(c=>c!==category);p={...p};}
</script>
<div class="page-header"><div><p class="eyebrow">CLEAR RULES. CONSISTENT DECISIONS.</p><h1>Expense policy</h1><p>Version {p.version} · Publishing creates a new version for first-time submissions only.</p></div><button class="primary" onclick={save}><Icon name="check" size={17}/>Publish new version</button></div>
<div class="notice"><Icon name="lock"/><p>Submitted and returned claims keep the policy version from their first submission. Changes never rewrite their checks or approval history.</p></div>{#if error}<p class="form-error" role="alert">{error}</p>{/if}
<div class="policy-layout"><div><section class="panel"><div class="panel-heading"><h2>Policy rules</h2><span class="tag">15 configurable rules</span></div><div class="policy-rules">{#each ruleKeys as key}<div class="policy-rule"><label class="toggle-label"><input type="checkbox" bind:checked={p.rules[key].enabled}/><span><strong>{names[key]}</strong><small>{p.rules[key].explanation}</small></span></label>{#if monetary.includes(key)||['late','mileageDay'].includes(key)}<label class="rule-value">{monetary.includes(key)?'INR':key==='late'?'Days':'Kilometres'}<input aria-label={names[key]+' value'} type="number" min="0" step={key==='late'?'1':'.01'} value={monetary.includes(key)?inputMoney(p.rules[key].value):key==='mileageDay'?p.rules[key].value/1000:p.rules[key].value} onchange={(e)=>value(key,e.currentTarget.value)}/></label>{/if}</div>{/each}</div></section>
<section class="panel"><div class="panel-heading"><div><h2>Category limits & accounting codes</h2><p>Amounts in INR. GL codes are included in the simple accounting CSV.</p></div></div><div class="table-scroll"><table class="policy-table"><thead><tr><th>Category</th><th>Daily cap</th><th>Monthly cap</th><th>Receipt always</th><th>GL code</th></tr></thead><tbody>{#each categories as category}<tr><td>{category}</td><td><input aria-label={category+' daily limit'} type="number" min="0" value={inputMoney(p.dailyLimits[category])} onchange={(e)=>{try{p.dailyLimits[category]=decimal(e.currentTarget.value);}catch(e){error=(e as Error).message;}}}/></td><td><input aria-label={category+' monthly limit'} type="number" min="0" value={inputMoney(p.monthlyLimits[category])} onchange={(e)=>{try{p.monthlyLimits[category]=decimal(e.currentTarget.value);}catch(e){error=(e as Error).message;}}}/></td><td><label class="checkbox-hit"><input type="checkbox" aria-label={category+' receipt required'} checked={p.receiptCategories.includes(category)} onchange={(e)=>p.receiptCategories=e.currentTarget.checked?[...p.receiptCategories,category]:p.receiptCategories.filter(c=>c!==category)}/></label></td><td><input aria-label={category+' GL code'} bind:value={p.glCodes[category]} maxlength="40"/></td></tr>{/each}</tbody></table></div></section>
<section class="panel form-panel"><div class="panel-heading"><h2>Eligibility</h2></div>{#each ['allowedDepartments','allowedGrades'] as group}<h3>{group==='allowedDepartments'?'Departments':'Grades'}</h3>{#each Object.keys(p[group as 'allowedDepartments'|'allowedGrades']) as name}<details class="eligibility"><summary>{name}</summary><div class="checkbox-grid">{#each categories as category}<label><input type="checkbox" checked={p[group as 'allowedDepartments'|'allowedGrades'][name].includes(category)} onchange={(e)=>allowed(group as 'allowedDepartments'|'allowedGrades',name,category,e.currentTarget.checked)}/>{category}</label>{/each}</div></details>{/each}{/each}</section>
<section class="panel form-panel"><div class="panel-heading"><h2>Travel & approval settings</h2></div><div class="form-grid"><label>Mileage rate (INR / km)<input type="number" value={inputMoney(p.mileageRate)} onchange={(e)=>{try{p.mileageRate=decimal(e.currentTarget.value);}catch(e){error=(e as Error).message;}}}/></label><label>Per diem (INR / day)<input type="number" value={inputMoney(p.perDiem)} onchange={(e)=>{try{p.perDiem=decimal(e.currentTarget.value);}catch(e){error=(e as Error).message;}}}/></label><label class="span-2">Company holidays (YYYY-MM-DD, comma separated)<textarea bind:value={holidayText} rows="2"></textarea></label><label class="checkbox-label span-2"><input type="checkbox" bind:checked={p.secondLevel}/>Require a second assigned manager above the threshold</label><label>Second approval threshold (INR)<input type="number" value={inputMoney(p.secondLevelThreshold)} onchange={(e)=>{try{p.secondLevelThreshold=decimal(e.currentTarget.value);}catch(e){error=(e as Error).message;}}}/></label></div><p class="field-help">Second approval requires a different manager assigned to that employee. Demo employees Mira Vale and Isha Reed have two assigned managers. A claim cannot be approved by its owner or submitter.</p></section></div>
<aside><section class="panel form-panel policy-test"><div class="panel-heading"><div><h2>Test this policy</h2><p>Try changes before publishing.</p></div><Icon name="shield"/></div>{#if sample}<label>Sample claim<select bind:value={testId}>{#each app.data!.claims as c}<option value={c.id}>{c.number} · {c.title}</option>{/each}</select></label><label>First line amount (INR)<input type="number" min="0" step=".01" bind:value={testAmount}/></label><p class="field-help">A temporary copy is checked. No saved claim is edited.</p><Findings findings={testFindings} compact/>{:else}<p>Create a claim in an employee account to test it here. No claims are currently stored.</p>{/if}</section></aside></div>